command:
// 设置合集效应库的 ID
const itemUUID = "UUID";

// 检查效应库
let item = await fromUuid(itemUUID);
if (!item) {
    ui.notifications.error("效应库丢失！");
    return;
}

// 确认所调用效应的名称
const effectName = "某效应";
let effect = item.effects.find(e => e.name === effectName);

if (!effect) {
    ui.notifications.error("效应丢失！");
    return;
}

// 获取持续时间
const duration = effect.duration.seconds ? effect.duration.seconds : 0; // 确保其有持续时间

// 为拓可添加效果
await selectedToken.actor.createEmbeddedDocuments("ActiveEffect", [{
    name: effect.name,
    img: effect.img,
    duration: {
        seconds: duration,
        rounds: null,
        turns: null,
        startTime: null,
        combat: null
    },
    changes: effect.changes, // 确保具体的效果值被应用
    ...effect.system // 使用展开运算符确保所有其他效果属性被应用
}]);
